const body = $input.first().json.body || $input.first().json;
const action = body.action || 'list';
const cfToken = '${CLOUDFLARE_API_TOKEN}';
const cfZone = '${CLOUDFLARE_ZONE_ID}';
const baseUrl = `https://api.cloudflare.com/client/v4/zones/${cfZone}/dns_records`;
const headers = { 'Authorization': `Bearer ${cfToken}`, 'Content-Type': 'application/json' };

async function cfReq(method, url, data) {
  const opts = { method, url, headers, json: true };
  if (data) opts.body = data;
  return await this.helpers.httpRequest(opts);
}

// Use reliable DoH endpoints only
const dohResolvers = [
  { name: 'Cloudflare', url: 'https://cloudflare-dns.com/dns-query' },
  { name: 'Google', url: 'https://dns.google/resolve' }
];

async function dohQuery(domain, resolver) {
  try {
    const resp = await this.helpers.httpRequest({
      method: 'GET',
      url: `${resolver.url}?name=${domain}&type=A`,
      headers: { 'Accept': 'application/dns-json' },
      json: true,
      timeout: 8000
    });
    return { resolver: resolver.name, ok: resp.Status === 0, answers: (resp.Answer||[]).map(a => a.data) };
  } catch(e) { return { resolver: resolver.name, ok: false, error: e.message }; }
}

try {
  if (action === 'list') {
    let url = `${baseUrl}?per_page=100`;
    if (body.filter) url += `&name=${body.filter}`;
    if (body.type) url += `&type=${body.type}`;
    const resp = await cfReq.call(this, 'GET', url);
    const records = (resp.result||[]).filter(r => !r.name.startsWith('edns-')).map(r => ({
      id: r.id, name: r.name, type: r.type, content: r.content,
      proxied: r.proxied, ttl: r.ttl,
      tier: r.name.includes('.int.') ? 'private' : (r.proxied ? 'public-cdn' : 'public-direct'),
      managed_by: (r.comment||'').includes('external-dns') ? 'external-dns' : 'manual'
    }));
    return [{json: {status:'ok', count:records.length, records}}];
  }

  if (action === 'create') {
    const {name, type='A', content, proxied, ttl=1, comment=''} = body;
    if (!name || !content) throw new Error('Required: name, content');
    const isInt = name.includes('.int.');
    const shouldProxy = proxied !== undefined ? proxied : !isInt;
    const resp = await cfReq.call(this, 'POST', baseUrl, {
      type, name, content, proxied: shouldProxy, ttl: shouldProxy ? 1 : (ttl||300),
      comment: comment || `DNS Manager | ${new Date().toISOString()}`
    });
    if (!resp.success) throw new Error(JSON.stringify(resp.errors));
    return [{json: {status:'ok', action:'created', record: {id:resp.result.id, name:resp.result.name, content:resp.result.content, proxied:resp.result.proxied, tier: isInt?'private':'public'}}}];
  }

  if (action === 'update') {
    const {id, name, type, content, proxied, ttl} = body;
    if (!id && !name) throw new Error('Required: id or name');
    let recordId = id;
    if (!recordId) {
      const s = await cfReq.call(this, 'GET', `${baseUrl}?name=${name}`);
      if (!s.result || !s.result.length) throw new Error(`Not found: ${name}`);
      recordId = s.result[0].id;
    }
    const patch = {};
    if (content) patch.content = content;
    if (proxied !== undefined) patch.proxied = proxied;
    if (ttl) patch.ttl = ttl;
    if (type) patch.type = type;
    const resp = await cfReq.call(this, 'PATCH', `${baseUrl}/${recordId}`, patch);
    if (!resp.success) throw new Error(JSON.stringify(resp.errors));
    return [{json: {status:'ok', action:'updated', record: {id:resp.result.id, name:resp.result.name, content:resp.result.content, proxied:resp.result.proxied}}}];
  }

  if (action === 'delete') {
    let recordId = body.id;
    if (!recordId && body.name) {
      const s = await cfReq.call(this, 'GET', `${baseUrl}?name=${body.name}`);
      if (!s.result || !s.result.length) throw new Error(`Not found: ${body.name}`);
      recordId = s.result[0].id;
    }
    if (!recordId) throw new Error('Required: id or name');
    const resp = await cfReq.call(this, 'DELETE', `${baseUrl}/${recordId}`);
    if (!resp.success) throw new Error(JSON.stringify(resp.errors));
    return [{json: {status:'ok', action:'deleted', id: recordId}}];
  }

  if (action === 'health') {
    const resp = await cfReq.call(this, 'GET', `${baseUrl}?per_page=100&type=A`);
    const records = (resp.result||[]).filter(r => !r.name.startsWith('edns-') && !r.name.includes('.int.'));
    const results = [];
    for (const r of records.slice(0, 20)) {
      const checks = await Promise.all(dohResolvers.map(res => dohQuery.call(this, r.name, res)));
      const healthy = checks.every(c => c.ok);
      results.push({name:r.name, proxied:r.proxied, healthy, checks: checks.map(c=>({resolver:c.resolver, ok:c.ok, ips:c.answers||[], error:c.error}))});
    }
    const unhealthy = results.filter(r => !r.healthy);
    return [{json: {status:'ok', total:results.length, healthy:results.length-unhealthy.length, unhealthy:unhealthy.length, issues: unhealthy.length>0 ? unhealthy : undefined, all_records: results}}];
  }

  if (action === 'propagation') {
    if (!body.domain) throw new Error('Required: domain');
    const checks = await Promise.all(dohResolvers.map(r => dohQuery.call(this, body.domain, r)));
    const okChecks = checks.filter(c => c.ok);
    const propagated = okChecks.length === dohResolvers.length;
    return [{json: {status:'ok', domain:body.domain, propagated, coverage:`${okChecks.length}/${dohResolvers.length}`, resolvers:checks}}];
  }

  if (action === 'suggest') {
    const resp = await cfReq.call(this, 'GET', `${baseUrl}?per_page=100&type=A`);
    const existing = new Set((resp.result||[]).map(r => r.name));
    const services = ['grafana','prometheus','longhorn','argocd','openbao','wiki','gitea','vaultwarden','forgejo','it-tools','stirling-pdf','excalidraw','actual'];
    const suggestions = services.filter(s => !existing.has(`${s}.int.${BASE_DOMAIN}`)).map(s => ({
      name:`${s}.int.${BASE_DOMAIN}`, type:'A', content:'${METALLB_TRAEFIK_VIP}', proxied:false,
      note:'Covered by wildcard but explicit record improves monitoring visibility'
    }));
    return [{json: {status:'ok', suggestions, total:suggestions.length}}];
  }

  if (action === 'bulk') {
    const ops = body.operations || [];
    if (!ops.length) throw new Error('Required: operations array [{action,name,content,...}]');
    const results = [];
    for (const op of ops) {
      try {
        if (op.action === 'create') {
          const r = await cfReq.call(this, 'POST', baseUrl, {type:op.type||'A', name:op.name, content:op.content, proxied:!!op.proxied, ttl:op.ttl||1, comment:'Bulk DNS Manager'});
          results.push({name:op.name, ok:r.success});
        } else if (op.action === 'delete') {
          let rid = op.id;
          if (!rid && op.name) { const s = await cfReq.call(this,'GET',`${baseUrl}?name=${op.name}`); rid = s.result && s.result[0] ? s.result[0].id : null; }
          if (rid) { const r = await cfReq.call(this,'DELETE',`${baseUrl}/${rid}`); results.push({name:op.name||op.id, ok:r.success}); }
          else results.push({name:op.name, ok:false, error:'Not found'});
        }
      } catch(e) { results.push({name:op.name, ok:false, error:e.message}); }
    }
    return [{json: {status:'ok', action:'bulk', total:results.length, succeeded:results.filter(r=>r.ok).length, results}}];
  }

  if (action === 'stats') {
    const resp = await cfReq.call(this, 'GET', `${baseUrl}?per_page=100`);
    const records = (resp.result||[]).filter(r => !r.name.startsWith('edns-'));
    const byType = {}; const byTier = {};
    for (const r of records) {
      byType[r.type] = (byType[r.type]||0) + 1;
      const tier = r.name.includes('.int.') ? 'private' : (r.proxied ? 'public-cdn' : 'public-direct');
      byTier[tier] = (byTier[tier]||0) + 1;
    }
    return [{json: {status:'ok', total:records.length, by_type:byType, by_tier:byTier}}];
  }

  return [{json: {status:'error', message:`Unknown action: ${action}`, available:['list','create','update','delete','health','propagation','suggest','bulk','stats']}}];
} catch(e) { return [{json: {status:'error', message:e.message}}]; }
